from backend.copilot.tools.expert_avatar import (
    AVATAR_BEARD,
    AVATAR_COLORS,
    AVATAR_GLASSES,
    AVATAR_HAT,
    NOTION_CATEGORIES,
    NOTION_PART_COUNTS,
    avatar_color_for_token,
    build_avatar_url,
    seeded_avatar,
)

# Golden vectors generated by running the frontend's notionConfigForName over
# the same names. Literals, not a re-run of build_avatar_url, so a drift in the
# FNV/LCG constants, the draw order or the "none" odds fails here rather than
# letting the two sides diverge silently.
FRONTEND_SEEDED = {
    "Maria": "/avatars/notion/10-2-5-6-13-6-1-0-0-0.green.svg",
    "Frankie": "/avatars/notion/3-3-6-4-5-12-31-0-0-0.orange.svg",
    "Max": "/avatars/notion/4-1-10-0-2-0-48-0-0-0.red.svg",
    "Ana": "/avatars/notion/11-12-17-2-6-0-11-6-0-0.green.svg",
    "Otto": "/avatars/notion/11-12-11-10-7-0-32-5-0-0.teal.svg",
    "Jules": "/avatars/notion/12-5-13-13-3-9-2-0-0-2.yellow.svg",
    "Priya": "/avatars/notion/2-12-18-1-15-2-55-11-0-11.indigo.svg",
    "Sam": "/avatars/notion/4-11-0-1-13-0-0-6-0-16.red.svg",
    # Non-BMP character (emoji): pins hashSeed/_hash_seed to hash by code
    # point on both sides, not by UTF-16 code unit.
    "Otto 🤖": "/avatars/notion/7-10-18-11-6-5-37-3-0-1.teal.svg",
}


def test_seeding_matches_the_frontend():
    for name, expected in FRONTEND_SEEDED.items():
        assert build_avatar_url(name) == expected


def test_seeding_is_stable_and_case_insensitive():
    assert build_avatar_url("Maria") == build_avatar_url("maria")
    assert build_avatar_url("Maria") == build_avatar_url("Maria")


def test_every_seeded_part_is_in_range():
    for name in ("", "a", "Zoë", "a much longer expert name than usual"):
        parts, color = seeded_avatar(name)
        assert set(parts) == set(NOTION_CATEGORIES)
        for category, index in parts.items():
            assert 0 <= index < NOTION_PART_COUNTS[category]
        assert parts["details"] == 0
        assert color in AVATAR_COLORS


def test_named_looks_override_only_their_own_category():
    seeded, _ = seeded_avatar("Maria")
    url = build_avatar_url("Maria", glasses="sunglasses")
    indices = [int(part) for part in url.split("/")[-1].split(".")[0].split("-")]
    chosen = dict(zip(NOTION_CATEGORIES, indices))
    assert chosen["glasses"] in AVATAR_GLASSES["sunglasses"]
    for category in NOTION_CATEGORIES:
        if category != "glasses":
            assert chosen[category] == seeded[category]


def test_named_looks_resolve_inside_their_pool():
    for choice, pool in AVATAR_BEARD.items():
        url = build_avatar_url("Maria", beard=choice)
        indices = [int(p) for p in url.split("/")[-1].split(".")[0].split("-")]
        assert dict(zip(NOTION_CATEGORIES, indices))["beard"] in pool
    for choice, pool in AVATAR_HAT.items():
        url = build_avatar_url("Maria", hat=choice)
        indices = [int(p) for p in url.split("/")[-1].split(".")[0].split("-")]
        assert dict(zip(NOTION_CATEGORIES, indices))["accessories"] in pool


def test_an_unknown_named_look_falls_back_to_the_seeded_part():
    assert build_avatar_url("Maria", glasses="monocle") == build_avatar_url("Maria")


def test_color_token_maps_to_an_avatar_color():
    assert avatar_color_for_token("violet-300") == "violet"
    assert avatar_color_for_token("sky-500") == "sky"
    # Families that used to collapse onto one disc now each keep their own.
    assert avatar_color_for_token("emerald-300") == "emerald"
    assert avatar_color_for_token("teal-300") == "teal"
    assert avatar_color_for_token("chartreuse-300") is None
    assert avatar_color_for_token(None) is None
    assert build_avatar_url("Maria", color_token="violet-300").endswith(".violet.svg")
